//! Order maintenance in O(1) worst case: the machine program verified in Lean
//! (`lean/OM/Impl/TheoremsM.lean`), printed as Rust (`gen.rs`, generated by `lake exe extract`).
//!
//! `Om` runs the program: `Om::new` is `initWS`, and each operation is `opS op` (its argument
//! assignments are charged as in `opS`). Handles are the insertion counter: the k-th insertion
//! returns handle k.

pub mod gen;
pub mod rt;

use gen::Top;
use rt::{pk, W, M};

pub struct Om {
    pub m: M,
    t: Top,
}

impl Om {
    /// `initWS` with `K_B = kb` (the theorems need `kb ≥ 4`).
    pub fn new(kb: u64) -> Om {
        let mut m = M::new();
        let mut t = Top::default();
        t.l_kb = W::S(kb);
        gen::init_ws(&mut t, &mut m).expect("initialization failed");
        Om { m, t }
    }

    fn set(&mut self, f: fn(&mut Top) -> &mut W, v: u64) {
        self.m.cost += 2;
        let w = pk(W::S(v), &mut self.m);
        *f(&mut self.t) = w;
    }

    /// Insert a new first element; returns its handle.
    pub fn insert_first(&mut self) -> u64 {
        self.set(|t| &mut t.l_hx, 0);
        gen::insert_ws(&mut self.t, &mut self.m).expect("insertion failed");
        self.t.l_hy.as_u64()
    }

    /// Insert a new element after the element with handle `x`; returns its handle.
    pub fn insert_after(&mut self, x: u64) -> u64 {
        self.set(|t| &mut t.l_hx, 1);
        self.set(|t| &mut t.l_x, x);
        gen::insert_ws(&mut self.t, &mut self.m).expect("insertion failed");
        self.t.l_hy.as_u64()
    }

    /// Delete the element with handle `x`.
    pub fn delete(&mut self, x: u64) {
        self.set(|t| &mut t.l_x, x);
        gen::delete_ws(&mut self.t, &mut self.m).expect("deletion failed");
    }

    /// Whether the element with handle `x` comes before the one with handle `y`.
    pub fn order(&mut self, x: u64, y: u64) -> bool {
        self.set(|t| &mut t.l_x, x);
        self.set(|t| &mut t.l_y, y);
        gen::order_ws(&mut self.t, &mut self.m).expect("order query failed");
        self.t.l_r.nz()
    }
}
